<?php
require_once __DIR__ . '/tienda_helpers.php';
require_once __DIR__ . '/email_service.php';
$ctx=require_customer();$user=$ctx['usuario'];$clienteId=$ctx['cliente_id'];$pdo=db();$method=$_SERVER['REQUEST_METHOD'];

function checkout_data(PDO $pdo,int $clienteId):array{
 $cart=store_active_cart($pdo,$clienteId,false);$items=[];$subtotal=0.0;
 if($cart){$st=$pdo->prepare("SELECT d.id item_id,d.producto_id,d.cantidad,p.nombre,p.stock_actual,p.precio_venta,p.descuento,ROUND(p.precio_venta*(1-LEAST(GREATEST(COALESCE(p.descuento,0),0),100)/100),2) precio_actual FROM carrito_detalle d JOIN productos p ON p.id=d.producto_id WHERE d.carrito_id=? AND p.estado='activo' ORDER BY d.id");$st->execute([$cart['id']]);$items=$st->fetchAll();foreach($items as &$it){$it['cantidad']=(int)$it['cantidad'];$it['precio_actual']=(float)$it['precio_actual'];$it['subtotal']=round($it['precio_actual']*$it['cantidad'],2);$subtotal+=$it['subtotal'];}unset($it);}
 $st=$pdo->prepare("SELECT id,etiqueta,calle,numero_exterior,numero_interior,colonia,municipio,estado,codigo_postal,pais,referencias,es_predeterminada FROM cliente_direcciones WHERE cliente_id=? AND estado_registro='activa' ORDER BY es_predeterminada DESC,id DESC");$st->execute([$clienteId]);$addresses=$st->fetchAll();
 $w=store_wallet($pdo,$clienteId);$tax=store_tax($pdo);$st=$pdo->query('SELECT saldo_minimo_alerta FROM tienda_configuracion WHERE id=1');$low=(float)($st->fetchColumn()?:100);
 return ['carrito_id'=>$cart['id']??null,'items'=>$items,'subtotal'=>round($subtotal,2),'direcciones'=>$addresses,'saldo_monedero'=>(float)$w['saldo'],'alerta_monedero'=>(float)$w['saldo']<=$low,'saldo_minimo_alerta'=>$low,'iva_porcentaje'=>$tax];
}
if($method==='GET')json_response(['ok'=>true]+checkout_data($pdo,$clienteId));
if($method!=='POST')json_response(['error'=>'Método no permitido.'],405);
require_csrf();$d=body_json();$payment=clean_string($d['metodo_pago']??'');$addressId=(int)($d['direccion_id']??0);$newAddress=$d['direccion']??null;$promoCode=strtoupper(clean_string($d['codigo_promocion']??''));
if(!in_array($payment,['monedero','tarjeta','paypal','transferencia'],true))json_response(['error'=>'Selecciona un método de pago válido.'],422);
$pdo->beginTransaction();
try{
 $cart=store_active_cart($pdo,$clienteId,false);if(!$cart)throw new RuntimeException('Tu carrito está vacío.');
 $st=$pdo->prepare("SELECT id,estado FROM carritos WHERE id=? AND cliente_id=? FOR UPDATE");$st->execute([$cart['id'],$clienteId]);$cartRow=$st->fetch();if(!$cartRow||$cartRow['estado']!=='activo')throw new RuntimeException('El carrito ya fue procesado.');
 $st=$pdo->prepare("SELECT d.producto_id,d.cantidad,p.nombre,p.stock_actual,p.precio_venta,p.descuento,p.estado FROM carrito_detalle d JOIN productos p ON p.id=d.producto_id WHERE d.carrito_id=? FOR UPDATE");$st->execute([$cart['id']]);$rows=$st->fetchAll();if(!$rows)throw new RuntimeException('Tu carrito está vacío.');
 $items=[];$subtotal=0.0;
 foreach($rows as $p){$qty=(int)$p['cantidad'];if($p['estado']!=='activo')throw new RuntimeException('El curso '.$p['nombre'].' ya no está disponible.');if($qty<1||$qty>(int)$p['stock_actual'])throw new RuntimeException('Inventario insuficiente para '.$p['nombre'].'.');$price=store_product_price($p);if($price<=0)throw new RuntimeException('No se permite comprar productos con precio cero.');$line=round($price*$qty,2);$subtotal+=$line;$items[]=['producto_id'=>(int)$p['producto_id'],'cantidad'=>$qty,'precio'=>$price,'subtotal'=>$line,'nombre'=>$p['nombre']];}
 $subtotal=round($subtotal,2);if($subtotal<=0)throw new RuntimeException('No se permiten compras con importe cero.');
 $promo=null;$discount=0.0;if($promoCode!==''){$promo=store_promo($pdo,$promoCode,true,(int)$clienteId);if(!$promo)throw new RuntimeException('El código promocional no existe, venció o ya alcanzó su límite de usos.');$discount=$promo['tipo_descuento']==='porcentaje'?$subtotal*((float)$promo['valor']/100):(float)$promo['valor'];$discount=min($subtotal,round($discount,2));}
 $base=round($subtotal-$discount,2);$taxRate=store_tax($pdo);$tax=round($base*$taxRate/100,2);$total=round($base+$tax,2);if($total<=0)throw new RuntimeException('El total de compra debe ser mayor que cero.');
 if($addressId){$st=$pdo->prepare("SELECT id FROM cliente_direcciones WHERE id=? AND cliente_id=? AND estado_registro='activa' FOR UPDATE");$st->execute([$addressId,$clienteId]);if(!$st->fetch())throw new RuntimeException('La dirección seleccionada no pertenece a tu cuenta.');}
 elseif(is_array($newAddress)){
  $required=['calle','numero_exterior','colonia','municipio','estado','codigo_postal'];foreach($required as $f)if(trim((string)($newAddress[$f]??''))==='')throw new RuntimeException('Completa los datos de la dirección de contacto/facturación.');
  $pdo->prepare('UPDATE cliente_direcciones SET es_predeterminada=0 WHERE cliente_id=?')->execute([$clienteId]);
  $st=$pdo->prepare('INSERT INTO cliente_direcciones(cliente_id,etiqueta,calle,numero_exterior,numero_interior,colonia,municipio,estado,codigo_postal,pais,referencias,es_predeterminada) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$clienteId,trim((string)($newAddress['etiqueta']??'Facturación')),trim((string)$newAddress['calle']),trim((string)$newAddress['numero_exterior']),trim((string)($newAddress['numero_interior']??''))?:null,trim((string)$newAddress['colonia']),trim((string)$newAddress['municipio']),trim((string)$newAddress['estado']),trim((string)$newAddress['codigo_postal']),trim((string)($newAddress['pais']??'México')),trim((string)($newAddress['referencias']??''))?:null,1]);$addressId=(int)$pdo->lastInsertId();
 }else{throw new RuntimeException('Selecciona o registra una dirección de contacto/facturación.');}
 if($payment==='monedero'){$wallet=store_wallet($pdo,$clienteId,true);if((float)$wallet['saldo']<$total)throw new RuntimeException('Saldo insuficiente. Saldo actual: $'.number_format((float)$wallet['saldo'],2).' MXN; total: $'.number_format($total,2).' MXN. Recarga tu monedero para continuar.');}
 $folio='WEB-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
 $paymentRef=match($payment){'monedero'=>'WAL-'.strtoupper(bin2hex(random_bytes(4))),'tarjeta'=>'CARD-'.strtoupper(bin2hex(random_bytes(4))),'paypal'=>'PAYPAL-'.strtoupper(bin2hex(random_bytes(4))),'transferencia'=>'TRF-'.strtoupper(bin2hex(random_bytes(4)))};
 $payState=$payment==='monedero'?'aprobado':'aprobado_simulado';
 $st=$pdo->prepare("INSERT INTO erp_ordenes(folio,cliente_id,fecha,estado,total,subtotal,impuesto_porcentaje,impuesto_monto,descuento_monto,promocion_id,origen,usuario_id,usuario_cliente_id,direccion_id,metodo_pago,pago_estado,correo_recibo_estado) VALUES(?,?,NOW(),'procesada',?,?,?,?,?,?,'tienda',?,?,?,?,?,'pendiente')");
 $st->execute([$folio,$clienteId,$total,$subtotal,$taxRate,$tax,$discount,$promo['id']??null,$user['id'],$user['id'],$addressId,$payment,$payState]);$orderId=(int)$pdo->lastInsertId();
 $ins=$pdo->prepare('INSERT INTO erp_orden_detalle(orden_id,producto_id,cantidad,precio_unitario,subtotal) VALUES(?,?,?,?,?)');
 foreach($items as $it){$ins->execute([$orderId,$it['producto_id'],$it['cantidad'],$it['precio'],$it['subtotal']]);$pdo->prepare('UPDATE productos SET stock_actual=stock_actual-?,actualizado_en=NOW() WHERE id=?')->execute([$it['cantidad'],$it['producto_id']]);$detail='Compra web '.$folio.': salida automática de '.$it['cantidad'].' licencia(s) por pedido del cliente.';$pdo->prepare("INSERT INTO movimientos_inventario(producto_id,tipo,cantidad,motivo,detalle,fecha,usuario_id,orden_erp_id) VALUES(?,'salida',?,'venta',?,NOW(),?,?)")->execute([$it['producto_id'],$it['cantidad'],$detail,$user['id'],$orderId]);scm_maybe_generate_push_order($pdo,$it['producto_id'],$user['id'],$orderId);}
 $paymentDetails=['simulado'=>$payment!=='monedero','referencia'=>$paymentRef];if($payment==='transferencia')$paymentDetails+=['banco'=>'BBVA (entorno de demostración)','titular'=>'Upskill Academy (cuenta ficticia)','cuenta'=>'0000000000','clabe'=>'000000000000000000','concepto'=>'Pago de cursos Upskill Academy'];if($payment==='tarjeta')$paymentDetails+=['banco'=>'BBVA (demostración)','tarjeta'=>'•••• •••• •••• 4242'];if($payment==='paypal')$paymentDetails+=['cuenta'=>'comprador-demo@example.com'];
 $pdo->prepare('INSERT INTO tienda_pagos(orden_id,monto,metodo_pago,estado,referencia,detalles_json) VALUES(?,?,?,?,?,?)')->execute([$orderId,$total,$payment,$payState,$paymentRef,json_encode($paymentDetails,JSON_UNESCAPED_UNICODE)]);
 if($payment==='monedero'){$newBalance=round((float)$wallet['saldo']-$total,2);$pdo->prepare('UPDATE monederos SET saldo=?,actualizado_en=NOW() WHERE id=?')->execute([$newBalance,$wallet['id']]);$pdo->prepare("INSERT INTO monedero_movimientos(monedero_id,tipo,concepto,monto,saldo_resultante,metodo_pago,referencia,orden_id,usuario_id) VALUES(?,'compra',?,?,?,?,?,?,?)")->execute([$wallet['id'],'Compra '.$folio,-$total,$newBalance,'monedero',$paymentRef,$orderId,$user['id']]);}else{$newBalance=(float)store_wallet($pdo,$clienteId)['saldo'];}
 if($promo)$pdo->prepare('UPDATE promociones SET usos_actuales=usos_actuales+1,actualizado_en=NOW() WHERE id=?')->execute([$promo['id']]);
 $pdo->prepare("UPDATE carritos SET estado='convertido',actualizado_en=NOW() WHERE id=?")->execute([$cart['id']]);
 $pdo->prepare("INSERT INTO erp_orden_historial(orden_id,estado,descripcion,usuario_id) VALUES(?,'procesada',?,?)")->execute([$orderId,'Compra de tienda confirmada; pago '.$payState.'. Inventario SCM actualizado automáticamente.',$user['id']]);
 $pdo->commit();
 $st=$pdo->prepare('SELECT d.producto_id,d.cantidad,d.precio_unitario,d.subtotal,p.nombre FROM erp_orden_detalle d JOIN productos p ON p.id=d.producto_id WHERE d.orden_id=?');$st->execute([$orderId]);$orderItems=$st->fetchAll();
 $mailResult=tienda_enviar_recibo($user['correo'],$user['nombre'],['folio'=>$folio,'productos'=>$orderItems,'subtotal'=>$subtotal,'descuento_monto'=>$discount,'impuesto_porcentaje'=>$taxRate,'impuesto_monto'=>$tax,'total'=>$total,'metodo_pago'=>$payment]);
 $pdo->prepare('UPDATE erp_ordenes SET correo_recibo_estado=? WHERE id=?')->execute([$mailResult['sent']?'enviado':'pendiente_configuracion',$orderId]);
 $st=$pdo->query('SELECT saldo_minimo_alerta FROM tienda_configuracion WHERE id=1');$walletAlertLimit=(float)($st->fetchColumn()?:100);
 json_response(['ok'=>true,'pedido'=>['id'=>$orderId,'folio'=>$folio,'total'=>$total,'subtotal'=>$subtotal,'descuento'=>$discount,'iva_porcentaje'=>$taxRate,'iva'=>$tax,'metodo_pago'=>$payment,'pago_estado'=>$payState,'referencia'=>$paymentRef,'detalles_pago'=>$paymentDetails,'saldo_monedero'=>$newBalance,'alerta_monedero'=>($newBalance<=$walletAlertLimit),'saldo_minimo_alerta'=>$walletAlertLimit,'correo_enviado'=>$mailResult['sent'],'correo_estado'=>$mailResult['reason']],'mensaje'=>'Compra registrada correctamente.'],201);
}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[Upskill checkout] '.$e->getMessage());json_response(['error'=>'No fue posible completar la compra por un error interno. No vuelvas a enviar el pago sin revisar Mis pedidos.'],500);}catch(RuntimeException $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['error'=>$e->getMessage()],422);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[Upskill checkout] '.$e->getMessage());json_response(['error'=>'Ocurrió un error al procesar la compra. Revisa Mis pedidos antes de intentarlo de nuevo.'],500);}
